-- 배치는 캐시를 모른다

@Test
@Transactional
void 캐시가_모른다() {
    Member m = memberRepository.save(new Member("김", 20));
    em.flush();

    System.out.println("--- 배치로 지운다 ---");
    memberRepository.deleteAllInBatch();

    System.out.println("영속 상태: " + em.contains(m));
    Member found = memberRepository.findById(m.getId()).orElse(null);
    System.out.println("조회 결과: " + (found != null ? "있다" : "없다"));
}

