void cascade_동작() {
    Team t = new Team("A팀");
    em.persist(t);
    t.getMembers().add(new Member("a", 20, t));
    t.getMembers().add(new Member("b", 21, t));
    em.flush(); em.clear();

    System.out.println("--- teamRepository.deleteAll ---");
    teamRepository.deleteAll();
    em.flush();
}

