public interface MemberRepository extends JpaRepository<Member, Long> {
    long deleteByAgeLessThan(int age);
}

@Test
@Transactional
void 조건부_삭제() {
    for (int i = 0; i < 5; i++) em.persist(new Member("m" + i, i * 10));
    em.flush(); em.clear();

    long n = counter.count(() -> {
        long deleted = memberRepository.deleteByAgeLessThan(25);
        System.out.println("지운 건수: " + deleted);
        em.flush();
    });
    System.out.println("쿼리 " + n + "개");
}

